describe('startSupportAgent delivery worker', () => {
  const activeTimeouts = () =>
    process.getActiveResourcesInfo().filter((resource) => resource === 'Timeout').length;

  it('runs one delivery timer with ESCALATION_WEBHOOK_URL set and leaves none behind after stop', async () => {
    const before = activeTimeouts();
    const agent = await startSupportAgent(
      getConfig({
        ...bootEnv,
        API_PORT: '8191',
        ESCALATION_WEBHOOK_URL: 'http://127.0.0.1:9/escalations',
      }),
      capturingLogger().logger
    );
    const running = activeTimeouts();
    await agent.stop();

    expect({running: running - before, stopped: activeTimeouts() - before}).toEqual({
      running: 1,
      stopped: 0,
    });
  });

  it('starts one periodic timer, for the retention sweep alone, and warns about KU-14 when ESCALATION_WEBHOOK_URL is unset', async () => {
    const {lines, logger} = capturingLogger();
    const before = activeTimeouts();
    const agent = await startSupportAgent(getConfig({...bootEnv, API_PORT: '8192'}), logger);
    const running = activeTimeouts();
    await agent.stop();

    expect({running: running - before, lines}).toEqual({
      running: 1,
      lines: [
        expect.stringContaining('"event":"api.model"'),
        expect.stringContaining('"event":"auth.stand_in_login"'),
        expect.stringContaining('"event":"tms.stand_in"'),
        expect.stringContaining('KU-14'),
        ...Array(7).fill(expect.stringContaining('"event":"hooks.composed"')),
        expect.stringContaining('"event":"reader.deny_by_default"'),
      ],
    });
  });
});

